mapper.select:
SELECT p.id, p.user_id, u.nickname, u.avatar, p.real_name, p.student_id, p.school, p.english_level, p.cert_url, p.cert_no, p.introduction, p.introduction_en, p.service_types, p.hourly_rate, p.rating, p.total_orders, p.status, p.reject_reason, p.create_time FROM interpreter_profile p LEFT JOIN sys_user u ON p.user_id = u.id
p.status = #{status}
ORDER BY p.create_time DESC LIMIT #{offset}, #{size}

